def capitalize_after_colon(s):
    lowered = s.lower()
    chars = list(lowered)

    def cap_at(idx):
        for i in range(idx, len(chars)):
            if chars[i].isalpha():
                chars[i] = chars[i].upper()
                return

    cap_at(0)
    idx = lowered.find(": ")
    while idx != -1:
        cap_at(idx + 2)
        idx = lowered.find(": ", idx + 1)
    return "".join(chars)

def truncate_words_ellipsis(s, maxwords):
    words = s.split()
    if len(words) <= maxwords:
        return ' '.join(words)
    return ' '.join(words[:maxwords]) + '...'

def count_primes_in_range(a, b):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    return sum(1 for x in range(a, b + 1) if is_prime(x))

def is_balanced_within_depth(s, limit):
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    stack = []
    depth = 0
    max_depth = 0
    for c in s:
        if c in opens:
            stack.append(c)
            depth += 1
            max_depth = max(max_depth, depth)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
            depth -= 1
        else:
            return False
    return not stack and max_depth <= limit

def char_index_map(s):
    result = {}
    for i, c in enumerate(s):
        result.setdefault(c, []).append(i)
    return result

def longest_substring_without_repeat(s):
    best = ""
    start = 0
    seen = {}
    for i, ch in enumerate(s):
        if ch in seen and seen[ch] >= start:
            start = seen[ch] + 1
        seen[ch] = i
        if i - start + 1 > len(best):
            best = s[start:i+1]
    return best

def render_row_truncate_pad(cells, widths):
    parts = []
    for c, w in zip(cells, widths):
        if len(c) > w:
            parts.append(c[:w])
        else:
            parts.append(c.ljust(w))
    return " ".join(parts)

def sanitize_filename_lower(name):
    lowered = name.lower().replace(" ", "-")
    allowed = set("abcdefghijklmnopqrstuvwxyz0123456789-.")
    return "".join(c for c in lowered if c in allowed)

def is_balanced_ignoring_whitespace(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    stack = []
    for c in s:
        if c.isspace():
            continue
        if c in opens:
            stack.append(c)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
        else:
            return False
    return not stack

def local_maxima_indices(lst):
