def most_frequent_char(s):
    if not s:
        return ""
    freq = {}
    order = []
    for ch in s:
        if ch not in freq:
            freq[ch] = 0
            order.append(ch)
        freq[ch] += 1
    best = order[0]
    for ch in order[1:]:
        if freq[ch] > freq[best]:
            best = ch
    return best

def is_chronological_order(s1, s2):
    y1, m1, d1 = s1.split("-")
    y2, m2, d2 = s2.split("-")
    return (int(y1), int(m1), int(d1)) <= (int(y2), int(m2), int(d2))

def is_valid_card_display_format(s):
    groups = s.split(' ')
    if len(groups) != 4:
        return False
    for g in groups:
        if g == 'XXXX':
            continue
        if len(g) == 4 and g.isdigit():
            continue
        return False
    return True

def is_all_digits(s):
    if not s:
        return False
    return all(ch.isdigit() for ch in s) and all(ch in "0123456789" for ch in s)

def value_groups_min_size(d):
    groups = {}
    for k, v in d.items():
        groups.setdefault(v, []).append(k)
    return {v: sorted(ks) for v, ks in groups.items() if len(ks) > 1}

def index_of_first_capital(s):
    for i, c in enumerate(s):
        if c.isupper():
            return i
    return -1

def is_identity_matrix(m):
    n = len(m)
    for row in m:
        if len(row) != n:
            return False
    for i in range(n):
        for j in range(n):
            expected = 1 if i == j else 0
            if m[i][j] != expected:
                return False
    return True

def dedupe_consecutive(lst):
    out = []
    for x in lst:
        if not out or out[-1] != x:
            out.append(x)
    return out
